CREATE OR REPLACE FUNCTION public.validate_report_recipients() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; owner uuid; BEGIN SELECT owner_id INTO owner FROM public.pharmacies WHERE id=NEW.pharmacy_id; FOREACH recipient IN ARRAY NEW.recipient_ids LOOP IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=recipient AND email_confirmed_at IS NOT NULL) OR (recipient IS DISTINCT FROM owner AND NOT EXISTS(SELECT 1 FROM public.pharmacy_memberships WHERE pharmacy_id=NEW.pharmacy_id AND user_id=recipient AND is_active AND role IN ('manager','accountant') AND branch_id IS NULL AND coalesce(cardinality(branch_ids),0)=0)) THEN RAISE EXCEPTION 'Report recipient must be a verified owner or business-wide finance team member'; END IF; END LOOP; IF NEW.enabled AND cardinality(NEW.recipient_ids)=0 THEN RAISE EXCEPTION 'Choose at least one report recipient'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_report_recipients() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_ai_report_recipients BEFORE INSERT OR UPDATE ON public.ai_report_preferences FOR EACH ROW EXECUTE FUNCTION public.validate_report_recipients();
CREATE OR REPLACE FUNCTION public.require_invitation_password() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='accepted' AND OLD.status IS DISTINCT FROM 'accepted' AND EXISTS(SELECT 1 FROM public.account_onboarding WHERE user_id=auth.uid() AND password_required) THEN RAISE EXCEPTION 'Set your account password before accepting the invitation'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.require_invitation_password() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER require_invitation_password BEFORE UPDATE ON public.pharmacy_invites FOR EACH ROW EXECUTE FUNCTION public.require_invitation_password();